// minimalMMDB is a valid but empty MaxMind DB (IPv4, 1 node, 24-bit record size).
// No IPs map to any data record, so all lookups return empty results.
// Generated by hand-encoding the MMDB binary format:
//   - 1 node (6 bytes): left=1, right=1 (both point to node_count, meaning "no record")
//   - 16-byte data separator
//   - empty data section
//   - metadata marker + metadata map
var minimalMMDB = []byte{
	// Node 0 (24-bit record size = 6 bytes per node): left=1, right=1
	0x00, 0x00, 0x01, 0x00, 0x00, 0x01,
	// 16-byte data section separator
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
	// Metadata marker: \xAB\xCD\xEFMaxMind.com
	0xAB, 0xCD, 0xEF, 0x4D, 0x61, 0x78, 0x4D, 0x69,
	0x6E, 0x64, 0x2E, 0x63, 0x6F, 0x6D,
	// Metadata map (7 keys, type=map encoded as 0xE7)
	0xE7,
	// "binary_format_major_version" -> uint32(2)
	0x5B, 0x62, 0x69, 0x6E, 0x61, 0x72, 0x79, 0x5F,
	0x66, 0x6F, 0x72, 0x6D, 0x61, 0x74, 0x5F, 0x6D,
	0x61, 0x6A, 0x6F, 0x72, 0x5F, 0x76, 0x65, 0x72,
	0x73, 0x69, 0x6F, 0x6E, 0xC1, 0x02,
	// "binary_format_minor_version" -> uint32(0)
	0x5B, 0x62, 0x69, 0x6E, 0x61, 0x72, 0x79, 0x5F,
	0x66, 0x6F, 0x72, 0x6D, 0x61, 0x74, 0x5F, 0x6D,
	0x69, 0x6E, 0x6F, 0x72, 0x5F, 0x76, 0x65, 0x72,
	0x73, 0x69, 0x6F, 0x6E, 0xC1, 0x00,
	// "build_epoch" -> uint32(0)
	0x4B, 0x62, 0x75, 0x69, 0x6C, 0x64, 0x5F, 0x65,
	0x70, 0x6F, 0x63, 0x68, 0xC1, 0x00,
	// "database_type" -> string("test")
	0x4D, 0x64, 0x61, 0x74, 0x61, 0x62, 0x61, 0x73,
	0x65, 0x5F, 0x74, 0x79, 0x70, 0x65, 0x44, 0x74,
	0x65, 0x73, 0x74,
	// "ip_version" -> uint32(4)
	0x4A, 0x69, 0x70, 0x5F, 0x76, 0x65, 0x72, 0x73,
	0x69, 0x6F, 0x6E, 0xC1, 0x04,
	// "node_count" -> uint32(1)
	0x4A, 0x6E, 0x6F, 0x64, 0x65, 0x5F, 0x63, 0x6F,
	0x75, 0x6E, 0x74, 0xC1, 0x01,
	// "record_size" -> uint32(24)
	0x4B, 0x72, 0x65, 0x63, 0x6F, 0x72, 0x64, 0x5F,
	0x73, 0x69, 0x7A, 0x65, 0xC1, 0x18,
}

// mustMMDBReader opens minimalMMDB via FromBytes and panics on error.
// Used in tests that need a non-nil *maxminddb.Reader without real data.
func mustMMDBReader(t *testing.T) *maxminddb.Reader {
	t.Helper()
	r, err := maxminddb.FromBytes(minimalMMDB)
	if err != nil {
		t.Fatalf("failed to open minimal MMDB: %v", err)
	}
	return r
}

// allFiles returns all four database file paths for a manager.
func allFiles(m *GeoIPManager) []string {
	return []string{m.asnFile, m.countryFile, m.cityV4File, m.cityV6File}
}

// --- NewGeoIPManager ---

func TestNewGeoIPManager_PathConstruction(t *testing.T) {
	m := NewGeoIPManager("/data")
	want := filepath.Join("/data", "security", "geoip")
	if m.dataDir != want {
		t.Errorf("dataDir = %q, want %q", m.dataDir, want)
	}
	if m.asnFile != filepath.Join(want, "asn.mmdb") {
		t.Errorf("asnFile = %q", m.asnFile)
	}
	if m.countryFile != filepath.Join(want, "country.mmdb") {
		t.Errorf("countryFile = %q", m.countryFile)
	}
	if m.cityV4File != filepath.Join(want, "dbip-city-ipv4.mmdb") {
		t.Errorf("cityV4File = %q", m.cityV4File)
	}
	if m.cityV6File != filepath.Join(want, "dbip-city-ipv6.mmdb") {
		t.Errorf("cityV6File = %q", m.cityV6File)
	}
	if m.updateInterval != updateInterval {
		t.Errorf("updateInterval = %v, want %v", m.updateInterval, updateInterval)
	}
}

func TestNewGeoIPManager_EmptyDataDir(t *testing.T) {
	m := NewGeoIPManager("")
	if m == nil {
		t.Fatal("expected non-nil manager")
	}
	if m.dataDir == "" {
		t.Error("dataDir should not be empty even for empty input")
	}
}

// --- databasesExist ---

func TestDatabasesExist_AllMissing(t *testing.T) {
	m := NewGeoIPManager(t.TempDir())
	if m.databasesExist() {
		t.Error("expected false when no database files exist")
	}
}

func TestDatabasesExist_PartiallyPresent(t *testing.T) {
	dir := t.TempDir()
	m := NewGeoIPManager(dir)
	geoDir := filepath.Join(dir, "security", "geoip")
	if err := os.MkdirAll(geoDir, 0755); err != nil {
		t.Fatal(err)
	}
	// Create only the asn file — the rest are absent
	if err := os.WriteFile(m.asnFile, []byte{}, 0644); err != nil {
		t.Fatal(err)
	}
	if m.databasesExist() {
		t.Error("expected false when only some database files exist")
	}
}

func TestDatabasesExist_AllPresent(t *testing.T) {
	dir := t.TempDir()
	m := NewGeoIPManager(dir)
	geoDir := filepath.Join(dir, "security", "geoip")
	if err := os.MkdirAll(geoDir, 0755); err != nil {
		t.Fatal(err)
	}
	for _, f := range allFiles(m) {
		if err := os.WriteFile(f, []byte{}, 0644); err != nil {
			t.Fatal(err)
		}
	}
	if !m.databasesExist() {
		t.Error("expected true when all database files exist")
	}
}

// --- ShouldUpdate / LastUpdate ---

func TestShouldUpdate_NeverUpdated(t *testing.T) {
	m := NewGeoIPManager(t.TempDir())
	// lastUpdate is zero value — should report that update is needed
	if !m.ShouldUpdate() {
		t.Error("expected ShouldUpdate() == true for fresh manager")
	}
}

func TestShouldUpdate_JustUpdated(t *testing.T) {
	m := NewGeoIPManager(t.TempDir())
	m.lastUpdate = time.Now()
	if m.ShouldUpdate() {
		t.Error("expected ShouldUpdate() == false immediately after update")
	}
}

func TestShouldUpdate_UpdateIntervalExceeded(t *testing.T) {
	m := NewGeoIPManager(t.TempDir())
	// Simulate a lastUpdate older than the interval
	m.lastUpdate = time.Now().Add(-(updateInterval + time.Second))
	if !m.ShouldUpdate() {
		t.Error("expected ShouldUpdate() == true when interval exceeded")
	}
}

func TestLastUpdate_ReturnsLastUpdate(t *testing.T) {
	m := NewGeoIPManager(t.TempDir())
	before := time.Now()
	m.lastUpdate = before
	got := m.LastUpdate()
	if !got.Equal(before) {
		t.Errorf("LastUpdate() = %v, want %v", got, before)
	}
}

func TestLastUpdate_ZeroByDefault(t *testing.T) {
	m := NewGeoIPManager(t.TempDir())
	if !m.LastUpdate().IsZero() {
		t.Error("expected zero LastUpdate for fresh manager")
	}
}

// --- GetStatus ---

func TestGetStatus_NilDBs(t *testing.T) {
	m := NewGeoIPManager(t.TempDir())
	s := m.GetStatus()
	if !s.Enabled {
		t.Error("Enabled should always be true")
	}
	if s.ASNEnabled {
		t.Error("ASNEnabled should be false when asnDB is nil")
	}
	if s.CountryEnabled {
		t.Error("CountryEnabled should be false when countryDB is nil")
	}
	if s.CityEnabled {
		t.Error("CityEnabled should be false when cityDB is nil")
	}
	if s.DatabasesExist {
		t.Error("DatabasesExist should be false for an empty dir")
	}
	if !s.LastUpdate.IsZero() {
		t.Error("LastUpdate should be zero for fresh manager")
	}
}

func TestGetStatus_WithDBs(t *testing.T) {
	m := NewGeoIPManager(t.TempDir())
	m.cityV4DB = mustMMDBReader(t)
	m.countryDB = mustMMDBReader(t)
	m.asnDB = mustMMDBReader(t)

	s := m.GetStatus()
	if !s.Enabled {
		t.Error("Enabled should be true")
	}
	if !s.ASNEnabled {
		t.Error("ASNEnabled should be true when asnDB is set")
	}
	if !s.CountryEnabled {
		t.Error("CountryEnabled should be true when countryDB is set")
	}
	if !s.CityEnabled {
		t.Error("CityEnabled should be true when cityDB is set")
	}
}

