// --- loadDatabases error paths ---

func TestLoadDatabases_MissingDatabases(t *testing.T) {
	m := NewGeoIPManager(t.TempDir())
	err := m.loadDatabases()
	if err == nil {
		t.Fatal("expected error when no database files exist at all")
	}
}

// Per AI.md PART 19's fail-open mandate, loadDatabases is resilient
// per-file: one invalid/missing database must not prevent the others
// from loading successfully.
func TestLoadDatabases_InvalidFile_OthersStillLoad(t *testing.T) {
	dir := t.TempDir()
	m := NewGeoIPManager(dir)
	geoDir := filepath.Join(dir, "security", "geoip")
	if err := os.MkdirAll(geoDir, 0755); err != nil {
		t.Fatal(err)
	}
	// asn is invalid; the rest are valid minimal MMDB files.
	if err := os.WriteFile(m.asnFile, []byte("not an mmdb"), 0644); err != nil {
		t.Fatal(err)
	}
	for _, f := range []string{m.countryFile, m.cityV4File, m.cityV6File} {
		if err := os.WriteFile(f, minimalMMDB, 0644); err != nil {
			t.Fatal(err)
		}
	}
	if err := m.loadDatabases(); err != nil {
		t.Fatalf("expected loadDatabases to succeed with 3/4 valid files, got: %v", err)
	}
	if m.asnDB != nil {
		t.Error("expected asnDB to remain nil after failing to load")
	}
	if m.countryDB == nil || m.cityV4DB == nil || m.cityV6DB == nil {
		t.Error("expected country/cityV4/cityV6 readers to be loaded despite asn failure")
	}
}

func TestLoadDatabases_AllFilesInvalid_ReturnsError(t *testing.T) {
	dir := t.TempDir()
	m := NewGeoIPManager(dir)
	geoDir := filepath.Join(dir, "security", "geoip")
	if err := os.MkdirAll(geoDir, 0755); err != nil {
		t.Fatal(err)
	}
	for _, f := range allFiles(m) {
		if err := os.WriteFile(f, []byte("not an mmdb"), 0644); err != nil {
			t.Fatal(err)
		}
	}
	if err := m.loadDatabases(); err == nil {
		t.Fatal("expected error when all database files are invalid")
	}
}

func TestLoadDatabases_ValidMinimalMMDB(t *testing.T) {
	dir := t.TempDir()
	m := NewGeoIPManager(dir)
	geoDir := filepath.Join(dir, "security", "geoip")
	if err := os.MkdirAll(geoDir, 0755); err != nil {
		t.Fatal(err)
	}
	// Write valid minimal MMDB to all four files
	for _, f := range allFiles(m) {
		if err := os.WriteFile(f, minimalMMDB, 0644); err != nil {
			t.Fatal(err)
		}
	}
	if err := m.loadDatabases(); err != nil {
		t.Fatalf("unexpected error loading valid MMDB files: %v", err)
	}
	if m.asnDB == nil || m.countryDB == nil || m.cityV4DB == nil || m.cityV6DB == nil {
		t.Error("expected all DB readers to be non-nil after successful load")
	}
}

// --- Initialize ---

func TestInitialize_CreatesDirectory(t *testing.T) {
	dir := t.TempDir()
	m := NewGeoIPManager(dir)
	geoDir := filepath.Join(dir, "security", "geoip")
	// Remove it if created by parent
	os.RemoveAll(geoDir)
	// Initialize will fail at download step, but should create the directory first.
	// Pre-populate valid files so Initialize succeeds without network access.
	if err := os.MkdirAll(geoDir, 0755); err != nil {
		t.Fatal(err)
	}
	for _, f := range allFiles(m) {
		if err := os.WriteFile(f, minimalMMDB, 0644); err != nil {
			t.Fatal(err)
		}
	}
	if err := m.Initialize(); err != nil {
		t.Fatalf("Initialize failed: %v", err)
	}
	if _, err := os.Stat(geoDir); os.IsNotExist(err) {
		t.Error("expected geoip directory to exist after Initialize")
	}
	if m.lastUpdate.IsZero() {
		t.Error("expected lastUpdate to be set after Initialize")
	}
}

// Per AI.md PART 19's fail-open mandate, a corrupt asn.mmdb must not take
// down GeoIP entirely — Initialize succeeds and serves the other databases.
func TestInitialize_CorruptAsnFile_FailsOpen(t *testing.T) {
	dir := t.TempDir()
	m := NewGeoIPManager(dir)
	geoDir := filepath.Join(dir, "security", "geoip")
	if err := os.MkdirAll(geoDir, 0755); err != nil {
		t.Fatal(err)
	}
	// Write valid MMDB to all files except asn, which gets corrupt data
	for _, f := range []string{m.countryFile, m.cityV4File, m.cityV6File} {
		if err := os.WriteFile(f, minimalMMDB, 0644); err != nil {
			t.Fatal(err)
		}
	}
	if err := os.WriteFile(m.asnFile, []byte("this is not a valid mmdb file"), 0644); err != nil {
		t.Fatal(err)
	}
	if err := m.Initialize(); err != nil {
		t.Fatalf("expected Initialize to fail open with a corrupt asn file, got: %v", err)
	}
	if m.GetStatus().ASNEnabled {
		t.Error("expected ASNEnabled false after asn file failed to load")
	}
	if !m.GetStatus().CountryEnabled {
		t.Error("expected CountryEnabled true — country file was valid")
	}
}

// --- Update ---

func TestUpdate_SkipsWhenRecentlyUpdated(t *testing.T) {
	m := NewGeoIPManager(t.TempDir())
	m.lastUpdate = time.Now()
	// Should not attempt download or load — returns nil immediately
	if err := m.Update(); err != nil {
		t.Fatalf("Update() should be no-op when recently updated: %v", err)
	}
}

// --- downloadFile ---

func TestDownloadFile_Success(t *testing.T) {
	content := []byte("fake mmdb content for test")
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		w.Write(content)
	}))
	defer srv.Close()

	dir := t.TempDir()
	m := NewGeoIPManager(dir)
	dest := filepath.Join(dir, "test.mmdb")

	if err := m.downloadFile(srv.URL, dest); err != nil {
		t.Fatalf("downloadFile failed: %v", err)
	}
	got, err := os.ReadFile(dest)
	if err != nil {
		t.Fatalf("ReadFile failed: %v", err)
	}
	if string(got) != string(content) {
		t.Errorf("downloaded content = %q, want %q", got, content)
	}
}

func TestDownloadFile_HTTP404(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.NotFound(w, r)
	}))
	defer srv.Close()

	dir := t.TempDir()
	m := NewGeoIPManager(dir)
	err := m.downloadFile(srv.URL, filepath.Join(dir, "out.mmdb"))
	if err == nil {
		t.Fatal("expected error for HTTP 404")
	}
}

func TestDownloadFile_HTTP500(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Error(w, "boom", http.StatusInternalServerError)
	}))
	defer srv.Close()

	dir := t.TempDir()
	m := NewGeoIPManager(dir)
	err := m.downloadFile(srv.URL, filepath.Join(dir, "out.mmdb"))
	if err == nil {
		t.Fatal("expected error for HTTP 500")
	}
}

func TestDownloadFile_ConnectionRefused(t *testing.T) {
	dir := t.TempDir()
	m := NewGeoIPManager(dir)
	// Use a port that is not listening
	err := m.downloadFile("http://127.0.0.1:0/noexist", filepath.Join(dir, "out.mmdb"))
	if err == nil {
		t.Fatal("expected error when connection is refused")
	}
}

func TestDownloadFile_UnwritableDestination(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("data"))
	}))
	defer srv.Close()

	m := NewGeoIPManager(t.TempDir())
	// Use a path inside a non-existent directory
	err := m.downloadFile(srv.URL, "/nonexistent/dir/file.mmdb")
	if err == nil {
		t.Fatal("expected error when destination directory does not exist")
	}
}

// --- DownloadDatabases (file path verification) ---

func TestDownloadDatabases_FilePathsCorrect(t *testing.T) {
	dir := t.TempDir()
	m := NewGeoIPManager(dir)
	geoDir := filepath.Join(dir, "security", "geoip")

	// Validate file paths are correctly derived from the data dir
	if m.asnFile != filepath.Join(geoDir, "asn.mmdb") {
		t.Errorf("asnFile path mismatch: %q", m.asnFile)
	}
	if m.countryFile != filepath.Join(geoDir, "country.mmdb") {
		t.Errorf("countryFile path mismatch: %q", m.countryFile)
	}
	if m.cityV4File != filepath.Join(geoDir, "dbip-city-ipv4.mmdb") {
		t.Errorf("cityV4File path mismatch: %q", m.cityV4File)
	}
	if m.cityV6File != filepath.Join(geoDir, "dbip-city-ipv6.mmdb") {
		t.Errorf("cityV6File path mismatch: %q", m.cityV6File)
	}
}

// --- ForceUpdate (error propagation) ---

func TestForceUpdate_FailsWhenNoNetwork(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping network test in short mode")
	}
	m := NewGeoIPManager(t.TempDir())
	// ForceUpdate calls DownloadDatabases which tries real CDN URLs.
	// This should fail in an offline/CI context with a network error.
	// We accept either a download error or a load error.
	err := m.ForceUpdate()
	if err == nil {
		// Acceptable only if we accidentally have network + valid CDN responses
		// (rare in test environments but possible); skip rather than fail
		t.Skip("ForceUpdate succeeded unexpectedly (network available with valid CDN)")
	}
}

// --- minimalMMDB self-check ---

func TestMinimalMMDB_ParsesCorrectly(t *testing.T) {
	r, err := maxminddb.FromBytes(minimalMMDB)
	if err != nil {
		t.Fatalf("minimalMMDB failed to parse: %v", err)
	}
	if r.Metadata.IPVersion != 4 {
		t.Errorf("IPVersion = %d, want 4", r.Metadata.IPVersion)
	}
	if r.Metadata.NodeCount != 1 {
		t.Errorf("NodeCount = %d, want 1", r.Metadata.NodeCount)
	}
	if r.Metadata.RecordSize != 24 {
		t.Errorf("RecordSize = %d, want 24", r.Metadata.RecordSize)
	}
}

func TestMinimalMMDB_LookupReturnsEmpty(t *testing.T) {
	r, err := maxminddb.FromBytes(minimalMMDB)
	if err != nil {
		t.Fatalf("minimalMMDB failed to parse: %v", err)
	}
	var result map[string]interface{}
	if err := r.Lookup(net.ParseIP("8.8.8.8"), &result); err != nil {
		t.Fatalf("Lookup failed: %v", err)
	}
	if len(result) != 0 {
		t.Errorf("expected empty result, got %v", result)
	}
}
